import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Ledger Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/ledger-lifecycle.md","filePath":"architecture/ledger-lifecycle.md","lastUpdated":1787151563000}'),i={name:"architecture/ledger-lifecycle.md"};function d(o,e,n,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="ledger-lifecycle" tabindex="-1">Ledger Lifecycle <a class="header-anchor" href="#ledger-lifecycle" aria-label="Permalink to &quot;Ledger Lifecycle&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>StrawMoneyBook 幾乎所有功能都以**活動帳本（active ledger）**為上下文。帳本切換、reload、完整性檢查與跨 Store 重置，由 <code>ledger-runtime.service.js</code> 協調，而非單一 Store 獨揽。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名詞</th><th>說明</th></tr></thead><tbody><tr><td>Active ledger</td><td>目前 UI 操作的帳本 ID，存在 <code>ledger.store</code></td></tr><tr><td>Ledger context</td><td>帳本幣別、時區、預算期間模式（曆月 / 發薪週期）</td></tr><tr><td>Critical path reload</td><td>切帳本後優先載入帳戶、分類、目前預算</td></tr><tr><td>Integrity scan</td><td>啟動 / 切帳本時掃描 FK、壞轉帳群組等（<strong>只掃不修</strong>）</td></tr><tr><td>Explicit repair</td><td>使用者於資料管理頁確認後才執行的修復</td></tr></tbody></table><h2 id="生命週期流程" tabindex="-1">生命週期流程 <a class="header-anchor" href="#生命週期流程" aria-label="Permalink to &quot;生命週期流程&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [*] --&gt; SelectLedger: 使用者選帳本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SelectLedger --&gt; ResetStores: ledger-runtime</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ResetStores --&gt; LoadCritical: accounts categories budget</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LoadCritical --&gt; BackgroundHydrate: loans reimbursements recent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  BackgroundHydrate --&gt; Ready: UI 可操作</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Ready --&gt; SwitchLedger: 切換帳本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SwitchLedger --&gt; ResetStores</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Ready --&gt; ScanOnly: integrity scan</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ScanOnly --&gt; ToastHint: 異常提示還原</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ScanOnly --&gt; Ready: 無異常</span></span></code></pre></div><h2 id="cross-store-協調" tabindex="-1">Cross-Store 協調 <a class="header-anchor" href="#cross-store-協調" aria-label="Permalink to &quot;Cross-Store 協調&quot;">​</a></h2><p>切換帳本時，<code>ledger-runtime.service.js</code> 會重置或 reload 相關 Store：</p><table tabindex="0"><thead><tr><th>Store</th><th>切換後行為</th></tr></thead><tbody><tr><td><code>account.store</code></td><td>重載帳戶與群組統計</td></tr><tr><td><code>category.store</code></td><td>重載分類樹</td></tr><tr><td><code>transaction.store</code></td><td>清空快取、重載首頁範圍</td></tr><tr><td><code>budget.store</code></td><td><code>loadCurrentPeriod()</code> 解析發薪週期 key</td></tr><tr><td><code>loan.store</code> / <code>reimbursement.store</code></td><td>背景 hydrate</td></tr></tbody></table><p><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/stores/ledger.store.js" target="_blank" rel="noreferrer"><code>ledger.store.js</code></a> 保留帳本 CRUD、活動帳本 ID、預算期間設定；cross-store 編排已外移到 runtime service。</p><h2 id="預算期間與帳本時區" tabindex="-1">預算期間與帳本時區 <a class="header-anchor" href="#預算期間與帳本時區" aria-label="Permalink to &quot;預算期間與帳本時區&quot;">​</a></h2><p>發薪週期帳本使用 <code>pay:YYYY-MM-DD</code> 形式的 <code>period_key</code>：</p><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/services/budget.service.js" target="_blank" rel="noreferrer"><code>budget.service.js</code></a> 的 <code>resolveCurrentBudgetPeriodForLedger()</code> 以<strong>帳本時區</strong>解析「今天」</li><li>App resume / focus 時重新載入目前期間，避免跨發薪日仍顯示舊期</li><li>改發薪日或切換曆月 ↔ 發薪週期時，若新期無內容可 carry-forward 舊期結構</li></ul><h2 id="integrity-scan-vs-repair" tabindex="-1">Integrity：Scan vs Repair <a class="header-anchor" href="#integrity-scan-vs-repair" aria-label="Permalink to &quot;Integrity：Scan vs Repair&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">smb297 後語意</p><ul><li><strong>Scan</strong>：啟動 / 切帳本時只報告問題，不靜默改寫資料</li><li><strong>Repair</strong>：必須在資料管理頁經使用者明示確認（含 audit reason）</li><li><strong>Sync replace</strong>：Google Drive / 共同帳本替換本機時 <code>runIntegrityRepair: false</code></li></ul></div><p>完整 wipe 僅允許明確 UX 路徑：重設全部資料、確認後 JSON 匯入、確認後雲端還原。且 wipe 前須建立 <strong>verified durable recovery backup</strong>，失敗則 <code>RECOVERY_BACKUP_REQUIRED</code> 中止。</p><h2 id="與同步域的銜接" tabindex="-1">與同步域的銜接 <a class="header-anchor" href="#與同步域的銜接" aria-label="Permalink to &quot;與同步域的銜接&quot;">​</a></h2><ul><li>共同帳本 pull / push 以帳本 snapshot 為單位，合併前後需保留本機快照以便失敗回滾</li><li>Google Drive 帳本同步使用三方合併（base + local dirty + remote）</li><li>詳見 <a href="/domains/sync-backup-shared-ledger.html">Sync, Backup &amp; Shared Ledger</a></li></ul><h2 id="關鍵程式入口" tabindex="-1">關鍵程式入口 <a class="header-anchor" href="#關鍵程式入口" aria-label="Permalink to &quot;關鍵程式入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>連結</th></tr></thead><tbody><tr><td>Ledger store</td><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/stores/ledger.store.js" target="_blank" rel="noreferrer"><code>ledger.store.js</code></a></td></tr><tr><td>Ledger runtime</td><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/ui/services/ledger-runtime.service.js" target="_blank" rel="noreferrer"><code>ledger-runtime.service.js</code></a></td></tr><tr><td>Ledger repository</td><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/repositories/ledger.repo.js" target="_blank" rel="noreferrer"><code>ledger.repo.js</code></a></td></tr><tr><td>Repair（明示確認）</td><td><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/services/repair.service.js" target="_blank" rel="noreferrer"><code>repair.service.js</code></a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/data-model-and-storage.html">Data Model &amp; Storage</a></li><li><a href="/domains/budget.html">Budget</a></li></ul>`,23)])])}const u=t(i,[["render",d]]);export{p as __pageData,u as default};
